const rtdal005410Source0005 = `file_path_site_unix <- function(
  sys_getenv,
  appname,
  version,
  multipath = FALSE
) {
  paths <- parse_path_string(sys_getenv)
  if (multipath) {
    vapply(
      paths,
      file_path,
      appname,
      version,
      FUN.VALUE = character(1),
      USE.NAMES = FALSE
    )
  } else {
    file_path(paths[[1]], appname, version)
  }
}`

