const rtdal005411Source0001 = `user_log_dir <- function(
  appname = NULL,
  appauthor = appname,
  version = NULL,
  opinion = TRUE,
  expand = TRUE,
  os = NULL
) {
  version <- check_version(version, appname, expand)

  switch(
    check_os(os),
    win = file_path(
      win_path("local"),
      appauthor,
      appname,
      version,
      if (opinion) "Logs"
    ),
    mac = file_path("~/Library/Logs", appname, version),
    unix = file_path(
      Sys.getenv("XDG_CACHE_HOME", "~/.cache"),
      appname,
      version,
      if (opinion) "log"
    )
  )
}`

