const rtdal005413Source0001 = "check_os <- function(os) {\n  if (is.null(os)) {\n    get_os()\n  } else {\n    if (length(os) != 1 || !is.character(os)) {\n      stop(\"`os` must be a string\", call. = FALSE)\n    }\n    if (!os %in% c(\"win\", \"mac\", \"unix\")) {\n      stop(\"`os` must be one of 'win', 'mac', 'unix'\", call. = FALSE)\n    }\n    os\n  }\n}"

const rtdal005413Source0002 = `get_os <- function() {
  if (.Platform$OS.type == "windows") {
    "win"
  } else if (Sys.info()["sysname"] == "Darwin") {
    "mac"
  } else {
    "unix"
  }
}`

const rtdal005413Source0003 = `file_path <- function(...) {
  paste(c(...), collapse = .Platform$file.sep)
}`

const rtdal005413Source0004 = `"%||%" <- function(a, b) if (is.null(a)) b else a`

const rtdal005413Source0005 = `base_path <- function(os, type, win, mac, unix) {
  name <- paste0("R_USER_", type, "_DIR")
  val <- Sys.getenv(name)

  if (!identical(val, "")) {
    val
  } else {
    switch(check_os(os), win = win, mac = mac, unix = unix)
  }
}`

const rtdal005413Source0008 = "win_path_env <- function(type) {\n  if (type == \"roaming\") {\n    env_fallback(\"APPDATA\")\n  } else if (type == \"local\") {\n    path <- Sys.getenv(\"LOCALAPPDATA\", unset = NA)\n    if (is.na(path)) {\n      # environmental variable not defined in XP\n      path <- file.path(\n        env_fallback(\"USERPROFILE\"),\n        \"Local Settings\",\n        \"Application Data\"\n      )\n    }\n    path\n  } else if (type == \"common\") {\n    path <- Sys.getenv(\"PROGRAMDATA\", unset = NA)\n    if (is.na(path)) {\n      path <- file.path(env_fallback(\"ALLUSERPROFILE\"), \"Application Data\")\n    }\n    path\n  } else {\n    stop(\"invalid `type` argument\")\n  }\n}"

const rtdal005413Source0009 = `env_fallback <- function(env) {
  val <- Sys.getenv(env)

  if (identical(val, "")) {
    if (get_os() == "win") {
      stop("Can't find envvar '", env, "'", call. = FALSE)
    } else {
      # Fall back so examples still work when not on windows
      paste0("<", env, ">")
    }
  } else {
    val
  }
}`

const rtdal005413Source0010 = `check_version <- function(version, appname, expand = FALSE) {
  if (is.null(appname) && !is.null(version)) {
    warning("version is ignored when appname is null", call. = FALSE)
    NULL
  } else {
    if (expand) {
      version <- expand_r_libs_specifiers(version)
    }
    version
  }
}`

