const rtdal005463Source0006 = `setMethod(cellFromRowColCombine, signature(object="BasicRaster", row="numeric", col="numeric"), 
	function(object, row, col) {
		# faster without this according to PR #131
		# object <- raster(object)
		row[row < 1 | row > object@nrows] <- NA
		col[col < 1 | col > object@ncols] <- NA
		cols <- rep(col, times=length(row))
		dim(cols) <- c(length(col), length(row))
		cols <- t(cols)
		row <- (row-1) * object@ncols
		cols <- cols + row
		as.vector(t(cols))
	}
)`

const rtdal005463Source0010 = `setMethod(cellFromRowCol, signature(object="BasicRaster", row="numeric", col="numeric"), 
	function(object, row, col, ...) {
		rows <- object@nrows
		cols <- object@ncols
		.doCellFromRowCol(rows, cols, row, col)
	}
)`

