const rtdal005473Source0001 = `.col2RGB <- function(x) {
	d <- t( grDevices::col2rgb(x@legend@colortable) )
	d <- data.frame(id=0:255, d)
	subs(x, d, which=2:4)
}`

const rtdal005473Source0002 = `.alphaCT <- function(x, alpha) {
	ct <- colortable(x)
	z <- t(grDevices::col2rgb(ct))
	ct <- apply(z, 1, function(i) grDevices::rgb(i[1], i[2], i[3], alpha*255, maxColorValue=255))
	colortable(x) <- ct
	return(x)
}`

