const rtdal005531Source0001 = `'gain<-' <- function(x, value) {
	value <- as.numeric(value[1])
	if (inherits(x, 'RasterStack')) {
		x@layers <- lapply( x@layers, 
			function(z) {
				if (fromDisk(z)) {
					z@data@gain <- value
				} else if (hasValues(z)) {
					z <- z * value
				}
				return(z)
			} 
		)
	} else {
		if (fromDisk(x)) {
			x@data@gain <- value
		} else if (hasValues(x)) {
			x <- x * value
		}
	}
	return(x)
}`

